// Transport validation only. Research/runtime configuration stays in ResearchForge V2.
const incoming = $input.first().json;
const fromWebhook = Object.prototype.hasOwnProperty.call(incoming, 'body');
const surface = fromWebhook ? 'webhook' : 'form';
const body = fromWebhook ? incoming.body : incoming;
const fail = (message) => [{ json: {
  ok: false, http_status: 422, schema_version: '2.0.0', status: 'error',
  code: 'INVALID_INPUT', message, run_id: null, links: null, surface,
} }];
if (!body || typeof body !== 'object' || Array.isArray(body)) return fail('请提交公司名称/股票代码和研究问题。');
const allowed = ['company_query', 'market_hint', 'requested_period_label', 'research_question', 'research_time', 'idempotency_key'];
const formMetadata = ['submittedAt', 'formMode'];
const raw = Object.fromEntries(Object.entries(body).filter(([key]) => !formMetadata.includes(key)));
const formFields = ['Company / 公司或股票代码', 'Market / 市场', 'Period / 报告期（可选）', 'Research Question / 研究问题'];
if (Object.keys(raw).some((key) => !(fromWebhook ? allowed : formFields).includes(key))) return fail('包含不支持的字段。');
const marketAliases = { 'Auto / 自动识别': null, 'A 股': 'CN', '美股': 'US', '港股': 'HK' };
const supplied = fromWebhook ? raw : {
  company_query: raw['Company / 公司或股票代码'],
  market_hint: marketAliases[raw['Market / 市场']] ?? null,
  requested_period_label: raw['Period / 报告期（可选）'] || null,
  research_question: raw['Research Question / 研究问题'],
};
if (typeof supplied.company_query !== 'string' || supplied.company_query.trim().length < 1 || supplied.company_query.length > 200 ||
    ![undefined, null, 'CN', 'US', 'HK'].includes(supplied.market_hint) ||
    typeof supplied.research_question !== 'string' || supplied.research_question.trim().length < 1 || supplied.research_question.length > 4000) {
  return fail('请检查公司名称/股票代码、市场和研究问题。');
}
const normalizedPeriod = typeof supplied.requested_period_label === 'string' ? supplied.requested_period_label.trim() : supplied.requested_period_label;
if (normalizedPeriod && !/^20[0-9]{2}(Q[1-3]|H1|FY)$/.test(normalizedPeriod)) return fail('报告期请使用 2025FY / 2025H1 / 2025Q1 等格式，留空表示 Latest。');
if (supplied.research_time !== undefined && (typeof supplied.research_time !== 'string' || !/T.*(Z|[+-][0-9]{2}:[0-9]{2})$/.test(supplied.research_time) || !Number.isFinite(Date.parse(supplied.research_time)))) {
  return fail('research_time 必须是含时区的 ISO 日期时间。');
}
return [{ json: {
  ok: true, surface,
  backend_url: 'http://api:8000', public_api_url: 'http://127.0.0.1:8000',
  started_at_ms: Date.now(), max_polls: 60, max_wait_ms: 150000,
  request: {
    company_query: supplied.company_query.trim(), market_hint: supplied.market_hint || null,
    requested_period_label: normalizedPeriod || null, research_question: supplied.research_question.trim(),
    research_time: supplied.research_time || new Date().toISOString(),
    idempotency_key: supplied.idempotency_key || `n8n-run-${$execution.id}`,
  },
} }];

const response = $input.first().json;
const ready = response.statusCode === 200 && response.body?.agent_ready === true && response.body?.version === '2.0.0-alpha.1';
if (!ready) {
  return [{ json: {
    ok: false, http_status: 502, schema_version: '2.0.0', status: 'error',
    code: 'BACKEND_UNAVAILABLE_OR_UNSAFE', run_id: null, links: null,
    message: 'ResearchForge V2 后端未就绪；未创建研究任务。',
  } }];
}
return [{ json: { ok: true } }];

const response = $input.first().json;
const config = $('Prepare request').first().json;
const id = response.body?.run_id;
if (response.statusCode !== 202 || typeof id !== 'string' || !/^run_[a-f0-9]{32}$/.test(id)) {
  const conflict = response.statusCode === 409;
  const invalid = response.statusCode === 422;
  return [{ json: {
    ok: false, http_status: conflict ? 409 : invalid ? 422 : 502,
    schema_version: '2.0.0', status: 'error', run_id: null, links: null,
    code: conflict ? 'IDEMPOTENCY_CONFLICT' : invalid ? 'UNSUPPORTED_OR_INVALID_INPUT' : 'SUBMISSION_UNCONFIRMED',
    message: conflict ? '该幂等键已用于不同输入；请还原原请求或使用新键。' :
      invalid ? (response.body?.detail?.message || 'V2 后端拒绝了公司、市场、期间或研究输入。') :
        '提交未获确认；请求可能已被接收。请使用原幂等键检查，不要重复创建任务。',
    retry_request: config.request,
  } }];
}
const path = `/v2/research-runs/${id}`;
return [{ json: {
  ok: true, run_id: id, path,
  links: {
    status: config.public_api_url + path,
    result: config.public_api_url + path + '/result',
    trace: config.public_api_url + path + '/trace',
    workspace: config.public_api_url + path + '/workspace',
    cancel: config.public_api_url + path + '/cancel',
  },
} }];

const response = $input.first().json;
const config = $('Prepare request').first().json;
const run = $('Accept submission').first().json;
const state = response.body?.lifecycle_state;
const polls = $runIndex + 1;
const base = { schema_version: '2.0.0', run_id: run.run_id, links: run.links, polls };
if (response.statusCode !== 200 || response.body?.run_id !== run.run_id) {
  return [{ json: { ...base, route: 'error', status: 'error', http_status: 502,
    code: 'STATUS_UNAVAILABLE', message: '无法确认 V2 后端任务状态；任务可能仍在运行。',
  } }];
}
if (state === 'succeeded') return [{ json: { ...base, route: 'completed' } }];
if (state === 'queued' || state === 'running') {
  if (polls < config.max_polls && Date.now() - config.started_at_ms < config.max_wait_ms) {
    return [{ json: { ...base, route: 'waiting', lifecycle_state: state } }];
  }
  return [{ json: { ...base, route: 'error', status: 'error', http_status: 504,
    code: 'POLL_LIMIT_EXCEEDED', message: 'n8n 达到等待上限；V2 后端任务未被自动取消。',
  } }];
}
const terminal = ['insufficient_data', 'failed', 'timed_out', 'cancelled'];
return [{ json: { ...base, route: 'error', status: 'error', http_status: 409,
  code: terminal.includes(state) ? `RUN_${state.toUpperCase()}` : 'UNKNOWN_BACKEND_STATE',
  message: state === 'insufficient_data' ? '可验证财报证据不足；没有生成报告。' :
    state === 'cancelled' ? '研究任务已取消。' : '研究任务没有可用结果；请检查状态与 Trace。',
} }];

// Presentation aliases only. All research, evidence, facts and calculations are V2 backend-owned.
const run = $('Accept submission').first().json;
const config = $('Prepare request').first().json;
const resultResponse = $('Fetch result').first().json;
const workspaceResponse = $('Fetch workspace').first().json;
const traceResponse = $('Fetch trace').first().json;
const result = resultResponse.body;
const workspace = workspaceResponse.body;
const trace = traceResponse.body;
const valid = [resultResponse, workspaceResponse, traceResponse].every((response) => response.statusCode === 200) &&
  result?.run_id === run.run_id && workspace?.run_id === run.run_id && trace?.run_id === run.run_id &&
  result?.schema_version === '2.0.0' && typeof result?.report?.executive_summary === 'string' &&
  Array.isArray(result?.report?.findings) && Array.isArray(result?.report?.sections) &&
  Array.isArray(workspace?.facts) && Array.isArray(workspace?.calculations) && Array.isArray(trace?.events);
if (!valid) {
  return [{ json: {
    schema_version: '2.0.0', status: 'error', http_status: 502, run_id: run.run_id,
    links: run.links, code: 'RESULT_ARTIFACTS_UNAVAILABLE',
    message: 'V2 报告或工作区产物不可用/不匹配；未把缺失内容呈现为成功。',
  } }];
}
return [{ json: {
  schema_version: '2.0.0', status: 'succeeded', http_status: 200,
  run_id: run.run_id, links: run.links, request: config.request,
  direct_answer: result.report.direct_answer,
  conclusion: result.report.executive_summary,
  findings: result.report.findings,
  analysis_sections: result.report.sections,
  limitations: result.report.limitations,
  follow_up_questions: result.report.follow_up_questions,
  financial_facts: workspace.facts,
  calculations: workspace.calculations,
  supporting_evidence: workspace.observed_evidence || [],
  hypotheses: workspace.working?.hypotheses || [],
  stop_decision: workspace.stop_decision || null,
  extraction_gaps: workspace.gaps || [],
  semantic_review: result.semantic_review,
  validation: result.validation,
  research_result: result,
  research_trace: trace,
  trust_boundary: 'n8n 只编排并展示同一 V2 backend 的持久化产物，不生成研究结论、财务数字或第二套状态。',
} }];

// Render only persisted V2 artifacts. This node does not create research content.
const incoming = $input.first().json;
const transport = { ...incoming };
delete transport.surface;
const escape = (value) => String(value ?? '')
  .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
  .replaceAll('"', '&quot;').replaceAll("'", '&#39;');
const safeUrl = (value) => /^https?:\/\//.test(String(value ?? '')) ? escape(value) : '#';
const list = (items) => items.length > 0 ? `<ul>${items.map((item) => `<li>${item}</li>`).join('')}</ul>` : '<p>无可呈现项目。</p>';
let content;
if (transport.status !== 'succeeded') {
  content = `<header><p class="eyebrow">BOUNDED FAILURE</p><h1>研究未生成</h1></header>
    <section class="failure"><p><strong>${escape(transport.code)}</strong> — ${escape(transport.message)}</p>
    <p>ResearchForge 在输入、来源、状态或产物无法确认时停止，不由 n8n 补写结论。</p>
    ${transport.links?.status ? `<p><a href="${safeUrl(transport.links.status)}">检查后端运行状态</a></p>` : ''}</section>`;
} else {
  const findings = transport.findings.map((finding) => `<strong>${escape(finding.title)}</strong><br>${escape(finding.text)}`);
  const analysis = transport.analysis_sections.map((section) => `<strong>${escape(section.title)}</strong><br>${escape(section.text)}`);
  const facts = transport.financial_facts.map((fact) => `<strong>${escape(fact.metric_code)}</strong>: ${escape(fact.value)} ${escape(fact.currency ?? '')}`);
  const calculations = transport.calculations.map((item) => `<strong>${escape(item.formula_code)}</strong>: ${escape(item.value ?? '不适用')}`);
  const hypotheses = transport.hypotheses.map((item) => `<strong>${escape(item.status)}</strong>: ${escape(item.statement)}`);
  const followUps = transport.follow_up_questions.map(escape);
  const evidence = transport.supporting_evidence.slice(0, 20).map((item) => `${escape(item.text ?? item.title ?? item.artifact_id)}`);
  content = `<header><p class="eyebrow">SAME V2 BACKEND · VERIFIED PIPELINE</p><h1>ResearchForge 研究完成</h1><span class="status">SUCCEEDED</span></header>
    <section class="conclusion"><h2>研究结论</h2><p>${escape(transport.conclusion)}</p>${transport.direct_answer && transport.direct_answer !== 'not_applicable' ? `<small>直接答案：${escape(transport.direct_answer)}</small>` : ''}</section>
    <details open><summary>关键发现</summary>${list(findings)}</details>
    <details open><summary>深入分析</summary>${list(analysis)}</details>
    <details><summary>财务事实</summary>${list(facts)}</details>
    <details><summary>确定性计算</summary>${list(calculations)}</details>
    <details><summary>已观察证据</summary>${list(evidence)}</details>
    <details><summary>假设与反向检验</summary>${list(hypotheses)}</details>
    <details><summary>限制与证据边界</summary>${list([...(transport.limitations || []), ...(transport.extraction_gaps || [])].map(escape))}</details>
    ${followUps.length ? `<details open><summary>进一步研究</summary>${list(followUps)}</details>` : ''}
    <nav><a href="${safeUrl(transport.links.result)}">完整 V2 Result</a><a href="${safeUrl(transport.links.trace)}">完整 V2 Trace</a><a href="${safeUrl(transport.links.workspace)}">完整 V2 Workspace</a></nav>
    <footer>${escape(transport.trust_boundary)}</footer>`;
}
const formPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ResearchForge V2 研究结果</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#dce4eb;background:#071015}*{box-sizing:border-box}body{margin:0;background:#071015}main{max-width:920px;margin:auto;padding:44px 22px 70px}.eyebrow{color:#43d6a3;font:11px ui-monospace,monospace;letter-spacing:.14em}header{position:relative;margin-bottom:22px}h1{margin:8px 0;color:#fff}.status{position:absolute;right:0;top:15px;color:#72e7bd}.conclusion,details,.failure{margin:12px 0;padding:18px;border:1px solid #23343e;border-radius:12px;background:#0d1921}.conclusion{border-left:3px solid #43d6a3}.conclusion p{font:17px/1.85 Georgia,serif}.conclusion small,li{color:#9eb0b9}summary{cursor:pointer;font-weight:650}li{margin:9px 0;line-height:1.65}a{color:#71d7b2}nav{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}nav a{padding:10px 12px;border:1px solid #285846;border-radius:8px;text-decoration:none}footer{margin-top:20px;color:#657d88;font:10px/1.7 ui-monospace,monospace}.failure{border-color:#663b3b;color:#ffaaa4}</style></head><body><main>${content}</main></body></html>`;
return [{ json: { transport, formPage } }];
